/* CTA global para el espejo: normaliza el acento y da una señal visual consistente
   a VER MÁS / SEE MORE, incluidos los enlaces que jQuery agrega después de cargar. */
(function ()
{
	function normalizeReadMoreLink(link)
	{
		if (!link || link.nodeType !== 1 || link.tagName !== "A") return;
		var label = (link.textContent || "").replace(/\s+/g, " ").trim().toUpperCase();
		if (label !== "VER MAS" && label !== "VER MÁS" && label !== "SEE MORE") return;
		if (label === "VER MAS") link.textContent = "VER MÁS";
		link.classList.add("vw-read-more");
	}

	function normalizeReadMoreLinks(root)
	{
		if (!root) return;
		if (root.nodeType === 1 && root.tagName === "A") normalizeReadMoreLink(root);
		var links = root.querySelectorAll ? root.querySelectorAll("a") : [];
		for (var index = 0; index < links.length; index++) normalizeReadMoreLink(links[index]);
	}

	function setupReadMoreLinks()
	{
		normalizeReadMoreLinks(document);
		new MutationObserver(function (mutations)
		{
			for (var mutationIndex = 0; mutationIndex < mutations.length; mutationIndex++)
			{
				var nodes = mutations[mutationIndex].addedNodes;
				for (var nodeIndex = 0; nodeIndex < nodes.length; nodeIndex++) normalizeReadMoreLinks(nodes[nodeIndex]);
			}
		}).observe(document.body, { childList: !0, subtree: !0 });
	}

	if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", setupReadMoreLinks);
	else setupReadMoreLinks();
})();
